/**
 * @module ui/Minimap
 * Corner minimap (toggle: M) rendering ONLY what the fog of war has
 * revealed: explored floors/walls in shadow tones, currently-visible tiles
 * brighter, the stairs in gold once discovered, and a pulsing player dot.
 *
 * Top-down orthographic (not isometric) for instant readability. Pure
 * DOM/canvas render layer: reads `Lighting.getState` + the dungeon grid and
 * writes nothing back. The explored base layer redraws only when the fog
 * changes (`markDirty`, wired to player:tileChanged); the player dot
 * composites every frame from the cached base.
 */

import { audio } from '@/engine/AudioManager';
import type { Lighting } from '@/engine/Lighting';
import { TILE_FLOOR, type DungeonMap } from '@/scenes/DungeonGenerator';

const SCALE = 4; // Canvas pixels per dungeon tile.

const COLOR_FLOOR_EXPLORED = '#3c372e';
const COLOR_FLOOR_VISIBLE = '#6a5f48';
const COLOR_WALL_EXPLORED = '#23202b';
const COLOR_WALL_VISIBLE = '#3a3444';
const COLOR_STAIRS = '#d8a83c';
const COLOR_PLAYER = '#e04a2f';

/** THE QUARRY'S MARKS (it.85): drawn only once their tile has been explored. */
export interface MapMarker {
  x: number;
  y: number;
  kind: 'key' | 'door' | 'door-open' | 'boss' | 'portal' | 'foe' | 'quest';
  /** A quest mark (it.91): drawn before the fog lifts. */
  always?: boolean;
}

export class MinimapUI {
  /** Marks on the map, read every frame; each shows only when its tile is out of the fog. */
  private markers: () => ReadonlyArray<MapMarker> = () => [];

  setMarkers(fn: () => ReadonlyArray<MapMarker>): void {
    this.markers = fn;
  }

  private readonly wrap: HTMLElement;
  private readonly canvas: HTMLCanvasElement;
  private readonly ctx: CanvasRenderingContext2D;
  private readonly base: HTMLCanvasElement;
  private readonly baseCtx: CanvasRenderingContext2D;

  private dungeon: DungeonMap | null = null;
  private lighting: Lighting | null = null;
  private stairs: { x: number; y: number } | null = null;
  private dirty = true;
  private visible = true;
  private readonly abort = new AbortController();
  /** CO-OP (it.59): the other heroes, drawn in their seat colours. */
  party: (() => Array<{ x: number; y: number; color: string; dead: boolean }>) | null = null;

  /** THE EXPANDED CHART (it.67): the same map, large, in the middle. */
  private expanded = false;

  constructor() {
    this.wrap = document.createElement('div');
    this.wrap.id = 'minimap';
    this.wrap.setAttribute('role', 'button');
    this.wrap.setAttribute('aria-label', 'Map — tap to enlarge');
    this.canvas = document.createElement('canvas');
    this.base = document.createElement('canvas');
    this.wrap.appendChild(this.canvas);
    // The chart's furniture: a title plaque and a close mark, seen only
    // while expanded.
    const head = document.createElement('div');
    head.className = 'mm-head';
    head.innerHTML = '<span>THE CHART</span><button class="tp-close" type="button" aria-label="Close map"><i></i></button>';
    this.wrap.appendChild(head);
    document.body.appendChild(this.wrap);
    this.ctx = this.canvas.getContext('2d')!;
    this.baseCtx = this.base.getContext('2d')!;

    // A TAP OPENS THE CHART (it.67): the corner map was too small to read on
    // a phone and the round clip hid its corners. A tap swells it to the
    // middle of the screen; a tap on the veil, the mark, ESC or M folds it
    // back. Acting on pointerup, one task late, for the same reason the
    // system bar does: the tap's click must not land in the chart.
    let down: number | null = null;
    this.wrap.addEventListener(
      'pointerdown',
      (e) => {
        e.preventDefault();
        e.stopPropagation();
        down = e.pointerId;
      },
      { signal: this.abort.signal },
    );
    this.wrap.addEventListener(
      'pointerup',
      (e) => {
        if (down !== e.pointerId) return;
        down = null;
        e.preventDefault();
        e.stopPropagation();
        window.setTimeout(() => this.setExpanded(!this.expanded), 0);
      },
      { signal: this.abort.signal },
    );
    this.wrap.addEventListener('contextmenu', (e) => e.preventDefault(), { signal: this.abort.signal });

    window.addEventListener(
      'keydown',
      (e: KeyboardEvent) => {
        if (e.code === 'Escape' && this.expanded) {
          // The chart is built before the pause sheet, so this listener runs
          // first: ESC folds the chart and goes no further — it must not
          // also pause the game.
          e.stopImmediatePropagation();
          this.setExpanded(false);
          return;
        }
        if (e.code === 'KeyM' && !e.repeat) {
          if (this.expanded) {
            this.setExpanded(false);
            return;
          }
          this.visible = !this.visible;
          this.wrap.classList.toggle('hidden', !this.visible);
          audio.sfx(this.visible ? 'mapOpen' : 'mapClose');
        }
      },
      { signal: this.abort.signal },
    );
  }

  get isExpanded(): boolean {
    return this.expanded;
  }

  setExpanded(on: boolean): void {
    if (this.expanded === on) return;
    this.expanded = on;
    this.wrap.classList.toggle('expanded', on);
    document.body.classList.toggle('map-expanded', on);
    audio.sfx(on ? 'mapOpen' : 'mapClose');
    if (on) this.dirty = true;
  }

  /** Run teardown (it.36). */
  destroy(): void {
    this.abort.abort();
    document.body.classList.remove('map-expanded');
    this.wrap.remove();
  }

  /** Bind to a floor's dungeon + fog state (called by each world build). */
  setWorld(dungeon: DungeonMap, lighting: Lighting, stairs: { x: number; y: number }): void {
    this.dungeon = dungeon;
    this.lighting = lighting;
    this.stairs = stairs;
    this.canvas.width = dungeon.width * SCALE;
    this.canvas.height = dungeon.height * SCALE;
    this.base.width = this.canvas.width;
    this.base.height = this.canvas.height;
    this.dirty = true;
  }

  /** Fog changed — the explored base layer needs a redraw. */
  markDirty(): void {
    this.dirty = true;
  }

  /** Per-render-frame composite: cached base + live player dot. */
  update(px: number, py: number, time: number): void {
    if (!this.visible || !this.dungeon || !this.lighting) return;
    if (this.dirty) {
      this.redrawBase();
      this.dirty = false;
    }
    const ctx = this.ctx;
    ctx.clearRect(0, 0, this.canvas.width, this.canvas.height);
    ctx.drawImage(this.base, 0, 0);

    // Party (it.59): steady colour-coded dots under the local pulse.
    if (this.party) {
      for (const m of this.party()) {
        ctx.fillStyle = m.color;
        ctx.globalAlpha = m.dead ? 0.35 : 1;
        ctx.beginPath();
        ctx.arc(m.x * SCALE, m.y * SCALE, 2.4, 0, Math.PI * 2);
        ctx.fill();
      }
      ctx.globalAlpha = 1;
    }
    // THE MARKS (it.85): keys, gates, the boss and the way home — never before the fog lifts.
    for (const m of this.markers()) {
      if (!m.always && this.lighting.getState(m.x, m.y) === 0) continue;
      const cx = m.x * SCALE + SCALE / 2;
      const cy = m.y * SCALE + SCALE / 2;
      ctx.save();
      ctx.lineWidth = 1;
      if (m.kind === 'key') {
        ctx.fillStyle = '#ffd070';
        ctx.strokeStyle = '#3a2a08';
        ctx.beginPath();
        ctx.arc(cx - 1.2, cy - 1.2, 1.9, 0, Math.PI * 2);
        ctx.fill();
        ctx.stroke();
        ctx.strokeStyle = '#ffd070';
        ctx.lineWidth = 1.6;
        ctx.beginPath();
        ctx.moveTo(cx, cy);
        ctx.lineTo(cx + 3.2, cy + 3.2);
        ctx.moveTo(cx + 2.2, cy + 2.2);
        ctx.lineTo(cx + 1.2, cy + 3.2);
        ctx.stroke();
      } else if (m.kind === 'door' || m.kind === 'door-open') {
        ctx.fillStyle = m.kind === 'door' ? '#d0303a' : '#5fc87f';
        ctx.strokeStyle = '#000';
        ctx.fillRect(cx - 3, cy - 3, 6, 6);
        ctx.strokeRect(cx - 3, cy - 3, 6, 6);
        ctx.fillStyle = '#000';
        ctx.fillRect(cx - 0.8, cy - 1.6, 1.6, 2.6);
      } else if (m.kind === 'foe') {
        // A LOOTER (it.91): a red pip, pulsing, wherever it stands.
        ctx.fillStyle = '#ff4a3a';
        ctx.strokeStyle = '#3a0808';
        ctx.beginPath();
        ctx.arc(cx, cy, 2.2 + Math.sin(time * 6 + m.x) * 0.4, 0, Math.PI * 2);
        ctx.fill();
        ctx.stroke();
      } else if (m.kind === 'quest') {
        /**
         * THE QUEST MARK (it.108): a gold star with a dark rim, and a soft ring
         * pulsing out of it so the eye finds it on a map the size of the town's.
         * Drawn `always` - a way that has just opened is exactly the thing a
         * player has not walked to yet.
         */
        const t = (performance.now() / 1000) % 1.6;
        ctx.strokeStyle = 'rgba(255, 214, 120, ' + (0.55 * (1 - t / 1.6)).toFixed(3) + ')';
        ctx.lineWidth = 1.4;
        ctx.beginPath();
        ctx.arc(cx, cy, 2.2 + t * 4.5, 0, Math.PI * 2);
        ctx.stroke();
        ctx.fillStyle = '#ffd670';
        ctx.strokeStyle = '#3a2a08';
        ctx.lineWidth = 1;
        ctx.beginPath();
        for (let i = 0; i < 10; i++) {
          const a = -Math.PI / 2 + (i * Math.PI) / 5;
          const rr = i % 2 === 0 ? 3.6 : 1.5;
          const px2 = cx + Math.cos(a) * rr;
          const py2 = cy + Math.sin(a) * rr;
          if (i === 0) ctx.moveTo(px2, py2);
          else ctx.lineTo(px2, py2);
        }
        ctx.closePath();
        ctx.fill();
        ctx.stroke();
      } else if (m.kind === 'boss') {
        ctx.fillStyle = '#ff5f5f';
        ctx.strokeStyle = '#000';
        ctx.beginPath();
        ctx.moveTo(cx, cy - 4);
        ctx.lineTo(cx + 4, cy);
        ctx.lineTo(cx, cy + 4);
        ctx.lineTo(cx - 4, cy);
        ctx.closePath();
        ctx.fill();
        ctx.stroke();
      } else {
        ctx.fillStyle = '#8fb8ff';
        ctx.strokeStyle = '#1a2a5a';
        ctx.beginPath();
        ctx.arc(cx, cy, 3 + Math.sin(time * 5) * 0.6, 0, Math.PI * 2);
        ctx.fill();
        ctx.stroke();
      }
      ctx.restore();
    }
    // Player: pulsing dot.
    const r = 2.6 + Math.sin(time * 6) * 0.7;
    ctx.fillStyle = COLOR_PLAYER;
    ctx.beginPath();
    ctx.arc(px * SCALE, py * SCALE, r, 0, Math.PI * 2);
    ctx.fill();
  }

  private redrawBase(): void {
    const { dungeon, lighting } = this;
    if (!dungeon || !lighting) return;
    const ctx = this.baseCtx;
    ctx.clearRect(0, 0, this.base.width, this.base.height);

    for (let gy = 0; gy < dungeon.height; gy++) {
      for (let gx = 0; gx < dungeon.width; gx++) {
        const state = lighting.getState(gx, gy);
        if (state === 0) continue; // HIDDEN: reveal nothing.
        const isFloor = dungeon.grid[gy * dungeon.width + gx] === TILE_FLOOR;
        const visible = state === 2;
        ctx.fillStyle = isFloor
          ? visible
            ? COLOR_FLOOR_VISIBLE
            : COLOR_FLOOR_EXPLORED
          : visible
            ? COLOR_WALL_VISIBLE
            : COLOR_WALL_EXPLORED;
        ctx.fillRect(gx * SCALE, gy * SCALE, SCALE, SCALE);
      }
    }

    // Stairs, once their tile has been revealed.
    if (this.stairs && lighting.getState(this.stairs.x, this.stairs.y) !== 0) {
      ctx.fillStyle = COLOR_STAIRS;
      ctx.fillRect(this.stairs.x * SCALE - 1, this.stairs.y * SCALE - 1, SCALE + 2, SCALE + 2);
    }
  }
}
